import numpy as np
for stage in ['initial','push_ball_toward_goal']:
 for c in ['front','left','right','topview']:
  a=np.array(Image.open(f'/app/output/{stage}_{c}.png')).astype(np.int16)
  v=a.mean(2);m=((a.max(2)-a.min(2))<7)&((v<100)|(v>195))
