  if c=='front':roi[82:145,25:285]=1
  elif c in ('left','right'):roi[75:210,90:230]=1
  else:roi[20:175,20:300]=1
  m &= roi; seen=np.zeros(m.shape,bool); vals=[]
  for y,x in zip(*np.where(m)):
   if seen[y,x]: continue
   stack=[(y,x)];seen[y,x]=1; pts=[]
   while stack:
    yy,xx=stack.pop();pts.append((yy,xx))
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      ny,nx=yy+dy,xx+dx
      if 0<=ny<240 and 0<=nx<320 and m[ny,nx] and not seen[ny,nx]: seen[ny,nx]=1;stack.append((ny,nx))
   if len(pts)>=4:
    ys=[p[0] for p in pts];xs=[p[1] for p in pts]; vals.append((len(pts),(min(xs),min(ys),max(xs)-min(xs)+1,max(ys)-min(ys)+1),(round(np.mean(xs),1),round(np.mean(ys),1))))
